using UnityEngine;

/// <summary>
/// One newspaper page's authored copy: the 13 named slots drawn over the
/// `news paper.png` backdrop. `demandsList` is deliberately NOT stored here — it
/// is generated by LegendController from the level's recipes. Lives in its own
/// asmdef (Sazon.LegendPage) so this pure model is reachable from EditModeTests.
/// </summary>
[CreateAssetMenu(fileName = "LegendPage", menuName = "Cards/Legend Page")]
public class LegendPage : ScriptableObject
{
    public string masthead;
    public string dateline;
    public string headline;
    public string subhead;
    public string reportHeader;
    public string reportBody;
    public string demandsHeader;
    public string adviceHeader;
    public string adviceBody;
    public string sidebarBlock1;
    public string sidebarBlock2;
    public string sidebarBlock3;
    public string footer;

    /// <summary>True when every slot is null/whitespace (treated as "no page").</summary>
    public bool IsEmpty()
    {
        return string.IsNullOrWhiteSpace(masthead)
            && string.IsNullOrWhiteSpace(dateline)
            && string.IsNullOrWhiteSpace(headline)
            && string.IsNullOrWhiteSpace(subhead)
            && string.IsNullOrWhiteSpace(reportHeader)
            && string.IsNullOrWhiteSpace(reportBody)
            && string.IsNullOrWhiteSpace(demandsHeader)
            && string.IsNullOrWhiteSpace(adviceHeader)
            && string.IsNullOrWhiteSpace(adviceBody)
            && string.IsNullOrWhiteSpace(sidebarBlock1)
            && string.IsNullOrWhiteSpace(sidebarBlock2)
            && string.IsNullOrWhiteSpace(sidebarBlock3)
            && string.IsNullOrWhiteSpace(footer);
    }
}
